// ---------------------------------------------------------------------------------------------
// The extension index.
//
// `ExtensionFactory` turns an element name + namespace into a model class, and both directions of
// that lookup used to come out of a javac annotation processor's generated
// `Extensions.EXTENSION_CLASS_MAP`. A javac processor cannot see Kotlin, so every model that
// converted had to be written a second time into a hand-maintained `ModelRegistry` - two maps for
// one fact, kept in step by hand. ClassGraph reads *classfiles*, so it sees the Kotlin and the Java
// models alike and the second map, and its drift, go away.
//
// The task scans the two compiled output trees of the debug variant and writes a sorted TSV,
// `namespace \t name \t binary-class`, with a `# tulkki-extension-index/1` header. Two details are
// load-bearing:
//
//  * the class is stored in its **binary** spelling (`Outer$Inner`). ClassGraph's
//    `ClassInfo.getName()` differs from the processor's `getQualifiedName()` for the nested
//    `error.Condition.*` and `sasl.SaslError.*` types, and `Class.forName` needs the `$` form.
//  * the file lands as a **java resource** (`variant.sources.resources` in the Variant API; the
//    legacy `sourceSets.main.resources` route is refused by AGP 9), read by `Class.getResourceAsStream`.
//    That is Context-free and needs no post-compile `aapt2` injection, so it cannot race AGP 9's
//    merge -> link -> compile order.
//
// `enableClasspathEntries` does not exist in ClassGraph 4.8.197 -- the wiki's recipe is wrong for
// the pinned version -- so the classpath is `overrideClasspath` over the two class dirs. ClassGraph
// and Guava come from the root buildscript's classpath (build.gradle.kts).
// ---------------------------------------------------------------------------------------------

val generateExtensionIndex = tasks.register<GenerateExtensionIndex>("generateExtensionIndex") {
    group = "build"
    description = "Writes the @XmlElement extension index as a java resource for ExtensionFactory"
    // The two compiled trees AGP produces for this variant, named exactly as AGP lays them out
    // (`javac/<variant>/<task>/classes` and `built_in_kotlinc/<variant>/<task>/classes`) and
    // ordered by `dependsOn`, which is resolved lazily at task-graph time and so cannot fail this
    // script's configuration. Reading the dirs off the tasks (`outputs.files`) would be less
    // coupled to AGP, but a Kotlin task that declared no output directory would then scan the Java
    // tree alone and write 120 plausible rows with nothing to warn anyone; here an absent tree is a
    // hard failure instead.
    dependsOn("compileDebugJavaWithJavac", "compileDebugKotlin")
    javaClassDirs.from(
        project.layout.buildDirectory.dir(
            "intermediates/javac/debug/compileDebugJavaWithJavac/classes"
        )
    )
    kotlinClassDirs.from(
        project.layout.buildDirectory.dir(
            "intermediates/built_in_kotlinc/debug/compileDebugKotlin/classes"
        )
    )
    outputDir.set(project.layout.buildDirectory.dir("generated/extensionIndex"))
}

configure<com.android.build.api.dsl.LibraryExtension> {
    namespace = "uk.xa0.tulkki.xmpp"
    compileSdk = 36
    defaultConfig {
        buildConfigField("String", "APP_NAME", "\"${rootProject.extra["appName"]}\"")
        buildConfigField("String", "VERSION_NAME", "\"${rootProject.extra["versionName"]}\"")
        // AGP 9's public library DSL has no `targetSdk` member: the Groovy `targetSdkVersion 36`
        // here landed on the legacy `BaseFlavor.targetSdkVersion(int)` through the closure's runtime
        // delegate, and a library's AAR carries none. Left out rather than emulated - reported.
        minSdk = 23
    }
    compileOptions {
        isCoreLibraryDesugaringEnabled = true
        sourceCompatibility = JavaVersion.VERSION_21
        targetCompatibility = JavaVersion.VERSION_21
    }
    buildFeatures {
        buildConfig = true
    }
    lint {
        disable += listOf("MissingTranslation", "InvalidPackage", "AppCompatResource")
        abortOnError = false
    }
}

// The index is read by name at runtime, so it must travel in the APK as a **java resource** -
// `Class.getResourceAsStream`, not `res`/aapt2 - and the task that writes it must run after both
// compile tasks. AGP 9 refuses the legacy route: `sourceSets.main.resources.srcDir(<task provider>)`
// fails at configuration with "You cannot add Provider instances to the Android SourceSet API".
// The Variant API is the supported wire, and `addGeneratedSourceDirectory` carries both halves the
// legacy call did not: it makes the resource-consuming task depend on `generateExtensionIndex` *and*
// reads the directory from its `@OutputDirectory` property. `variant.sources.resources` is the
// java-resource source set (never `sources.res`, the aapt2 one). The escape hatch AGP's error offers
// (`android.sourceset.disallowProvider=false`) is deliberately not taken: it silences the check while
// leaving the dependency uncarried, which is the ordering bug the check exists to prevent.
configure<com.android.build.api.variant.LibraryAndroidComponentsExtension> {
    onVariants(selector().all()) { variant ->
        variant.sources.resources?.addGeneratedSourceDirectory(generateExtensionIndex) { task ->
            task.outputDir
        }
    }
}

