/**
 * Scans the compiled model classes for `@XmlElement` and writes the sorted extension index.
 *
 * <p>Two of the annotation processor's guards survive as **build failures**, because both are
 * silent at runtime: a type that declares no namespace would produce an entry nobody can ever
 * resolve, and a type without a public no-arg constructor would produce an entry that resolves and
 * then throws. A third guard has no processor predecessor but the same silence: two types claiming
 * one `(name, namespace)` pair - the processor's `ImmutableSortedMap.Builder` refused that
 * outright, and a map built from a file would simply keep the last one.
 */
abstract class GenerateExtensionIndex : DefaultTask() {

    companion object {
        private const val INDEXED_PACKAGE = "uk.xa0.tulkki.xmpp.models"
        private const val XML_ELEMENT = "uk.xa0.tulkki.annotation.XmlElement"
        private const val HEADER = "# tulkki-extension-index/1"
        private const val RESOURCE_PATH = "uk/xa0/tulkki/xmpp/models/extension-index.txt"
    }

    /** `:xmpp`'s javac output: the models that are still Java. */
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val javaClassDirs: ConfigurableFileCollection

    /** `:xmpp`'s Kotlin output. A separate input because the scan must never silently lose it. */
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    abstract val kotlinClassDirs: ConfigurableFileCollection

    /** The java-resource tree `sourceSets.main.resources` consumes. */
    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @TaskAction
    fun generate() {
        val classpath = mutableListOf<File>()
        for (tree in listOf("java", "kotlin")) {
            val dirs = mutableListOf<File>()
            val entries = if (tree == "java") javaClassDirs.files else kotlinClassDirs.files
            for (entry in entries) {
                if (entry.isDirectory) {
                    dirs.add(entry)
                }
            }
            if (dirs.isEmpty()) {
                throw GradleException(
                    "generateExtensionIndex: the $tree class dir is empty or unreadable. Scanning " +
                        "only the other tree would write an index with entries missing, and nothing " +
                        "at runtime would warn you; the wiring of compileDebugJavaWithJavac / " +
                        "compileDebugKotlin is the thing to check."
                )
            }
            classpath.addAll(dirs)
        }
        val rows = mutableListOf<String>()
        val claimed = mutableMapOf<String, String>()
        val classGraph = ClassGraph()
            .overrideClasspath(classpath)
            .acceptPackages(INDEXED_PACKAGE)
            .enableClassInfo()
            .enableAnnotationInfo()
            .enableMethodInfo()
        classGraph.scan().use { scanResult ->
            for (classInfo in scanResult.getClassesWithAnnotation(XML_ELEMENT)) {
                val element: AnnotationInfo =
                    classInfo.getAnnotationInfo(XML_ELEMENT) ?: continue
                val namespace = string(element, "namespace")
                if (namespace.isNullOrEmpty()) {
                    throw GradleException(
                        "generateExtensionIndex: ${classInfo.name} declares no namespace. " +
                            "@XmlElement.namespace() is the only source now that @XmlPackage is " +
                            "gone, so this type could never be resolved by name."
                    )
                }
                var name = string(element, "name")
                if (name.isNullOrEmpty()) {
                    name = CaseFormat.UPPER_CAMEL.to(CaseFormat.LOWER_HYPHEN, classInfo.simpleName)
                }
                if (!hasPublicNoArgConstructor(classInfo)) {
                    throw GradleException(
                        "generateExtensionIndex: ${classInfo.name} has no public no-arg " +
                            "constructor, so the index would carry an entry ExtensionFactory " +
                            "cannot instantiate."
                    )
                }
                val key = namespace + "\t" + name
                val previous = claimed.put(key, classInfo.name)
                if (previous != null) {
                    throw GradleException(
                        "generateExtensionIndex: $previous and ${classInfo.name} both claim the " +
                            "($name, $namespace) pair, so one of them would silently never resolve."
                    )
                }
                rows.add(key + "\t" + classInfo.name)
            }
        }
        if (rows.isEmpty()) {
            throw GradleException(
                "generateExtensionIndex: no @XmlElement classes were found in $classpath. A green " +
                    "build here would ship an index that resolves nothing; the compiled class dirs " +
                    "are the thing to check."
            )
        }
        rows.sort()
        val target = File(outputDir.get().asFile, RESOURCE_PATH)
        target.parentFile.mkdirs()
        target.writeText(HEADER + "\n" + rows.joinToString("\n") + "\n", Charsets.UTF_8)
        logger.lifecycle("generateExtensionIndex: ${rows.size} entries -> $target")
    }

    private fun string(annotation: AnnotationInfo?, parameter: String): String? {
        val values = annotation?.parameterValues ?: return null
        return values.getValue(parameter)?.toString()
    }

    private fun hasPublicNoArgConstructor(classInfo: ClassInfo): Boolean {
        for (constructor in classInfo.constructorInfo) {
            if (constructor.isPublic && constructor.parameterInfo.isEmpty()) {
                return true
            }
        }
        return false
    }
}
